import{_ as e,o as d,c as a,ag as o}from"./chunks/framework.C5oN-8Wt.js";const b=JSON.parse('{"title":"符号映射器","description":"","frontmatter":{},"headers":[],"relativePath":"v0.3.0-alpha/modules/symbol_mapper/index.md","filePath":"v0.3.0-alpha/modules/symbol_mapper/index.md"}'),r={name:"v0.3.0-alpha/modules/symbol_mapper/index.md"};function l(c,t,n,i,s,h){return d(),a("div",null,[...t[0]||(t[0]=[o('<h1 id="符号映射器" tabindex="-1">符号映射器 <a class="header-anchor" href="#符号映射器" aria-label="Permalink to &quot;符号映射器&quot;">​</a></h1><p>适用：v0.3.0-alpha · GNU Radio 3.10.12.0<br> 模块类型：<code>symbol_mapper</code> · 模块定义版本：6</p><h2 id="是什么" tabindex="-1">是什么 <a class="header-anchor" href="#是什么" aria-label="Permalink to &quot;是什么&quot;">​</a></h2><p>按码元索引查找有序星座点表，输出对应复数坐标。它建立离散编号与 I/Q 的关系，是数字基带调制实验中的映射步骤。</p><h2 id="典型接线" tabindex="-1">典型接线 <a class="header-anchor" href="#典型接线" aria-label="Permalink to &quot;典型接线&quot;">​</a></h2><p><code>随机码元发生器.out → 符号映射器.in → 信道模拟器.in</code>。也可将映射器输出分支直接接符号判决器，作为不经信道的对照。<code>set_symbol_table</code> 是消息输入，不连接数值流。</p><p>下表为内置默认参数下的端口。带路数、元素类型或 vlen 的模块会随参数改变流端口。</p><table tabindex="0"><thead><tr><th>方向</th><th>端口</th><th>数据类型</th><th>单位 / 形状</th></tr></thead><tbody><tr><td>输入</td><td><code>in</code>（码元输入）</td><td><code>symbol_u8</code></td><td>索引；vlen=1</td></tr><tr><td>输入</td><td><code>set_symbol_table</code>（set_symbol_table（消息））</td><td><code>message</code></td><td>消息；不计入流路数</td></tr><tr><td>输出</td><td><code>out</code>（星座输出）</td><td><code>complex_f64</code></td><td>归一化幅度；vlen=1</td></tr></tbody></table><h2 id="参数怎么用" tabindex="-1">参数怎么用 <a class="header-anchor" href="#参数怎么用" aria-label="Permalink to &quot;参数怎么用&quot;">​</a></h2><p>点表顺序就是码元编号顺序。自定义表按每码元连续 D 个复数坐标排列，两张实虚部列表各含 M×D 项，不能独立排序。源、映射器与判决器应对编号保持一致。</p><p>D 大于 1 时，一个输入码元输出 D 个连续复数样本，输出率相应提高；它们不是一个向量 item。归一化按坐标的平均幅度或平均功率进行，不能据此认为多坐标码元的总能量也为 1。</p><p>内置默认值如下；本机设置可为<strong>新实例</strong>指定其他默认值，打开已有工程保留工程参数。</p><table tabindex="0"><thead><tr><th>参数</th><th>内置默认值</th><th>取值与约束</th><th>修改时机</th></tr></thead><tbody><tr><td>星座模式<br><code>constellation</code></td><td><code>qpsk</code></td><td>BPSK (<code>bpsk</code>)；QPSK (<code>qpsk</code>)；16QAM (<code>qam16</code>)；自定义 (<code>custom</code>)；预设按 I 后 Q 升序编号；BPSK 为 -1、+1，QPSK 除以 √2，16QAM 的 ±1/±3 网格除以 √10。自定义点表按输入顺序从 0 编号，可另选归一化方式。</td><td>可在线应用</td></tr><tr><td>按码元编号排列的点表实部<br><code>points_real</code></td><td><code>[-0.7071067811865475, -0.7071067811865475, 0.7071067811865475, 0.7071067811865475]</code></td><td>按字段类型填写，见下文说明</td><td>可在线应用</td></tr><tr><td>按码元编号排列的点表虚部<br><code>points_imag</code></td><td><code>[-0.7071067811865475, 0.7071067811865475, -0.7071067811865475, 0.7071067811865475]</code></td><td>按字段类型填写，见下文说明</td><td>可在线应用</td></tr><tr><td>点表归一化<br><code>normalization</code></td><td><code>none</code></td><td>保留原坐标 (<code>none</code>)；平均幅度为 1 (<code>amplitude</code>)；平均功率为 1 (<code>power</code>)</td><td>可在线应用</td></tr><tr><td>每个码元的连续复数坐标数 D<br><code>dimensionality</code></td><td><code>1</code></td><td>范围 1 至 1024；本版 D 支持 1–1024；自定义点表按码元顺序连续填写 M×D 个复数坐标，预设为 D=1。</td><td>重新准备</td></tr></tbody></table><h2 id="在线修改与重新准备" tabindex="-1">在线修改与重新准备 <a class="header-anchor" href="#在线修改与重新准备" aria-label="Permalink to &quot;在线修改与重新准备&quot;">​</a></h2><p>运行中可在线应用以下字段组；同组字段一起提交：</p><ul><li><code>constellation</code>、<code>points_real</code>、<code>points_imag</code>、<code>normalization</code></li></ul><p>其余计算字段需停止并重新准备。在线应用以该节点实际回执为准；编辑草稿本身不会改变已运行的图，旧缓存仍可能包含修改前的数据。</p><p>保持 M 和 D 不变时，点表设计可按组在线应用；改变码元数量或坐标分组后重新准备。原生消息更新表需保持 M×D 长度，消息本身不执行表单归一化。</p><p>当前属性页未提供 <code>set_symbol_table</code> 消息投递表单；消息接口由配套开发验证脚本等显式调用。打开工程后普通 F5 只运行工程中的初始图，不会重放上次消息更新。保存在源点表中的流标签属于图的定义，应与独立投递消息区分。</p><h2 id="下载与观察" tabindex="-1">下载与观察 <a class="header-anchor" href="#下载与观察" aria-label="Permalink to &quot;下载与观察&quot;">​</a></h2><h3 id="qpsk-映射、判决与理想信道" tabindex="-1">QPSK 映射、判决与理想信道 <a class="header-anchor" href="#qpsk-映射、判决与理想信道" aria-label="Permalink to &quot;QPSK 映射、判决与理想信道&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/qpsk-channel.cnsproj" download>下载 qpsk-channel.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>QPSK 映射、判决与理想信道</p><ul><li>直接判决逐码元一致。理想信道仍保留 GNU 原生 3 点前视，不能将信道两端同索引当作已对齐。</li></ul><h3 id="调频、幅相、正交解调与二值-bpsk-映射" tabindex="-1">调频、幅相、正交解调与二值 BPSK 映射 <a class="header-anchor" href="#调频、幅相、正交解调与二值-bpsk-映射" aria-label="Permalink to &quot;调频、幅相、正交解调与二值 BPSK 映射&quot;">​</a></h3><p><a href="../../../downloads/v0.3.0-alpha/modulation-chain.cnsproj" download>下载 modulation-chain.cnsproj</a></p><p>来源：PC 本地 GNU Radio 仿真。下载后打开工程，按 F5 运行；本次核验每例参考源运行 2048 item，工程不保存样本。</p><p>调频、幅相、正交解调与二值 BPSK 映射</p><ul><li>Fs=4096，常量 1 经 sensitivity=π/8 调频得到 +256 Hz、模长 1 的复相量，首项先累加。幅相输出主值相位；gain=8/π 解调首项为 0、后续约 1。二值判决对零和正值均输出索引 1，按生产 BPSK 点表映射。码元 OUT 固定 M2，不生成模拟幅度频谱。</li></ul><p>QPSK 示例把随机索引映射到四个复数点，绑定映射器输出并选择星座显示。每个点与一个索引相对应；直接判决支路用于核对这种编号关系。改变源的随机区间，可以只观察某一部分点。</p><h2 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h2><p><strong>点的位置正确，但判回的索引不对？</strong> 核对映射与判决的点表顺序，不要只比较散点形状。</p><p><strong>星座为什么没有平滑的点间轨迹？</strong> 本步骤输出离散坐标，没有自动加入脉冲成形、载波同步或连续调制波形。</p><h2 id="递进实验" tabindex="-1">递进实验 <a class="header-anchor" href="#递进实验" aria-label="Permalink to &quot;递进实验&quot;">​</a></h2><ul><li><a href="./../../learn/09-symbols/">09 码元、星座与判决</a></li></ul>',36)])])}const m=e(r,[["render",l]]);export{b as __pageData,m as default};
